import{_ as a,o as i,c as e,am as t}from"./chunks/framework._FJXuPhs.js";const d=JSON.parse('{"title":"面试煎熬成蛋_项目场景题","description":"","frontmatter":{"title":"面试煎熬成蛋_项目场景题","excerpt":"面试煎熬成蛋_项目场景题","date":"2024-03-10 20:35:44","updated":"2024-03-02 23:53:33"},"headers":[],"relativePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/面试煎熬成蛋_项目场景题.md","filePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/面试煎熬成蛋_项目场景题.md","lastUpdated":null}'),o={name:"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/面试煎熬成蛋_项目场景题.md"};function r(n,l,s,h,u,p){return i(),e("div",null,[...l[0]||(l[0]=[t('<h3 id="提前准备" tabindex="-1">提前准备 <a class="header-anchor" href="#提前准备" aria-label="Permalink to &quot;提前准备&quot;">​</a></h3><h4 id="遇到了哪些比较棘手的问题-怎么解决的" tabindex="-1">遇到了哪些比较棘手的问题，怎么解决的 <a class="header-anchor" href="#遇到了哪些比较棘手的问题-怎么解决的" aria-label="Permalink to &quot;遇到了哪些比较棘手的问题，怎么解决的&quot;">​</a></h4><p>！！ <strong>提前准备</strong></p><p>需要提前准备，重要度偏高，一般情况下问起项目的时候会问你有没有什么印象深刻的地方，你需要说一下：</p><ul><li>1、当时的业务背景，遇到了什么问题（技术问题）；</li><li>2、过程，在遇到这个问题你的解决思路和解决方案说一下（解决问题的过程）；</li><li>3、最终落地方案。（形成一个完整链路，并清晰表达出来）</li></ul><p>建议准备的一些点：</p><ul><li>1、设计模式 <ul><li>一般是工厂、策略、责任链... 等</li><li>阐述回答建议：先说一下改动和改动之后的一个比对，在没有使用到设计模式之前，会出现什么问题（比如需求经常变更，代码冗余程度较高，维护程度困难等）；通过实际调研，对代码进行了优化，后续的一个效果。</li></ul></li><li>2、线上 Bug <ul><li>在线上出现了：CPU 飙高、内存泄漏、线程死锁... 等</li><li>可能情况是： <ul><li>测试环境没问题，生产上线后出的问题，且问题不好在测试环境复现</li><li>生产上线初期没问题，上线一两个月后出现这种问题</li></ul></li><li>这种情况需要线上调试和排查（通过这种问题反馈你的实际处理经验和复盘，当时是如何操作的）</li></ul></li><li>3、调优 <ul><li>慢接口、慢SQL、缓冲方案 ... 等</li><li>可以将你的实际操作，包括如何排查出这个接口的处理速度慢，从多少秒调优到了多少 ms 这种程度。</li></ul></li><li>4、组件封装（不建议，一般是高级工程师操作）</li></ul><h3 id="系统登录" tabindex="-1">系统登录 <a class="header-anchor" href="#系统登录" aria-label="Permalink to &quot;系统登录&quot;">​</a></h3><h4 id="分布式认证授权" tabindex="-1">分布式认证授权 <a class="header-anchor" href="#分布式认证授权" aria-label="Permalink to &quot;分布式认证授权&quot;">​</a></h4><p>参考： <a href="https://www.bilibili.com/video/BV1nG4y1d7mf" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1nG4y1d7mf</a></p><ul><li><a href="https://www.bilibili.com/video/BV17D4y1Y76o" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV17D4y1Y76o</a></li></ul><h4 id="讲一下单点登陆的实现" tabindex="-1">讲一下单点登陆的实现 <a class="header-anchor" href="#讲一下单点登陆的实现" aria-label="Permalink to &quot;讲一下单点登陆的实现&quot;">​</a></h4><p>单点登录的英文名叫做：Single Sign On(简称SSO),只需要登录一次，就可以访问所有信任的应用系统</p><p>在单个 tomcat 中，session 是共享的，但是在多个 tomcat 服务中，session 是不共享的；</p><p>在这种情况下，常用的解决方案有：JWT (常见)、OAuth2、CAS （框架）</p><p>一般使用的是 JWT 的方式：</p><p>登陆流程分析：</p><ul><li>用户登陆 <ul><li>用户向认证服务器发送登录请求，通常包括用户名和密码。</li><li>认证服务器验证用户的身份。如果认证成功，服务器会使用一个密钥生成一个包含用户信息（如用户ID、角色等）和其他声明的JWT。然后，将这个JWT返回给用户。</li></ul></li><li>访问资源 <ul><li>用户带着JWT访问应用中的受保护资源。JWT通常在HTTP请求的 Authorization 头中以Bearer token的形式发送。</li><li>应用服务器接收到请求后，会提取JWT并验证它的有效性。验证包括检查签名是否有效、令牌是否过期等。</li><li>如果JWT验证成功，服务器就会根据令牌中的声明处理请求，比如返回用户请求的数据。</li></ul></li><li>使用JWT进行单点登录 <ul><li>在单点登录系统中，一旦用户在一个应用中登录并获取了JWT，他们就可以使用同一个令牌访问系统中的其他应用，而无需重新登录。（一般是网关进行验证，通过后访问具体服务）</li><li>当用户尝试访问另一个应用时，他们的浏览器会发送包含同一个JWT的请求。</li><li>第二个应用也会验证JWT的有效性。如果验证通过，用户就可以访问第二个应用的受保护资源，实现了单点登录。</li></ul></li><li>JWT 的刷新 <ul><li>为了安全起见，JWT通常会设置较短的过期时间。认证服务器可能会提供一个刷新令牌（Refresh Token）机制，允许用户在JWT过期后，无需重新登录就能获取一个新的JWT。</li><li>一般访问令牌和刷新令牌都会存放在客户端的内存中（一种常见的做法是将刷新令牌存储在HttpOnly的Cookie中。HttpOnly Cookie由于无法通过JavaScript访问）</li><li>在发送请求到服务器时，客户端会从存储中获取访问令牌，并将其放入HTTP请求的Authorization头中，通常采用<code>Bearer &lt;token&gt;</code>的格式。</li></ul></li></ul><h4 id="讲一下-jwt-的组成-使用-jwt-的优势有哪些" tabindex="-1">讲一下 Jwt 的组成，使用 jwt 的优势有哪些 <a class="header-anchor" href="#讲一下-jwt-的组成-使用-jwt-的优势有哪些" aria-label="Permalink to &quot;讲一下 Jwt 的组成，使用 jwt 的优势有哪些&quot;">​</a></h4><h4 id="登陆注销是怎么使用的-为什么不适用-sesson-而使用-jwt" tabindex="-1">登陆注销是怎么使用的，为什么不适用 sesson 而使用 jwt <a class="header-anchor" href="#登陆注销是怎么使用的-为什么不适用-sesson-而使用-jwt" aria-label="Permalink to &quot;登陆注销是怎么使用的，为什么不适用 sesson 而使用 jwt&quot;">​</a></h4><h4 id="使用账号密码访问流程-jwt-方式" tabindex="-1">使用账号密码访问流程（JWT 方式） <a class="header-anchor" href="#使用账号密码访问流程-jwt-方式" aria-label="Permalink to &quot;使用账号密码访问流程（JWT 方式）&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240330222111.png" alt="image.png"></p><h3 id="权限控制-数据安全" tabindex="-1">权限控制，数据安全 <a class="header-anchor" href="#权限控制-数据安全" aria-label="Permalink to &quot;权限控制，数据安全&quot;">​</a></h3><h4 id="你们项目中权限认证是如何实现的" tabindex="-1">你们项目中权限认证是如何实现的 <a class="header-anchor" href="#你们项目中权限认证是如何实现的" aria-label="Permalink to &quot;你们项目中权限认证是如何实现的&quot;">​</a></h4><p>最常见的就是 RBAC 模型来指导实现权限</p><p>RBAC(Role-Based Access Control)：基于角色的访问控制，一般是有3个基础部分组成：用户、角色、权限。</p><p>具体实现</p><ul><li>5张表（用户表、角色表、权限表、用户角色中间表、角色权限中间表）</li><li>7张表（用户表、角色表、权限表、菜单表、用户角色中间表、角色权限中间表、权限菜单中间表）</li></ul><p>常用的权限控制框架：Spring security</p><h4 id="上传数据的安全你们是如何控制的" tabindex="-1">上传数据的安全你们是如何控制的 <a class="header-anchor" href="#上传数据的安全你们是如何控制的" aria-label="Permalink to &quot;上传数据的安全你们是如何控制的&quot;">​</a></h4><p>使用非对称加密（或对称加密），给前端一个公钥让他把数据加密后传到后台，后台负责解密后处理数据</p><ul><li>文件很大建议使用对称加密，不过不能保存敏感信息</li><li>文件较小，要求安全性高，建议采用非对称加密</li></ul><p>考虑数据传输的话，可以从很多方面考虑，主要是你当初考虑的点，当时遇到了什么问题，然后通过什么方式去解决的。</p><ul><li>1、考虑权限认证</li><li>2、考虑文件类型限制，考虑大小限制</li><li>3、内容检查（不建议说，不太了解）</li><li>4、使用安全连接 <strong>HTTPS</strong></li><li>5、上面说的数据加密，可以谈一下关于对称加密和非对称加密的一些用法，当时技术选型是怎么做的，为什么选择了使用这一种加密算法（提前准备一下）</li></ul><h3 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h3><h4 id="你们项目中日志是怎么采集的" tabindex="-1">你们项目中日志是怎么采集的 <a class="header-anchor" href="#你们项目中日志是怎么采集的" aria-label="Permalink to &quot;你们项目中日志是怎么采集的&quot;">​</a></h4><p>为什么要采集日志：日志是定位系统问题的重要手段，可以根据日志信息快速定位系统中的问题</p><p>一般日志的采集方案有：</p><ul><li>ELK：即Elasticsearch、Logstash 和 Kibana三个软件的首字母（不建议回答这种，看你项目实际使用情况）</li><li>常规采集：按天保存到一个日志文件</li></ul><h4 id="常见日志的命令" tabindex="-1">常见日志的命令 <a class="header-anchor" href="#常见日志的命令" aria-label="Permalink to &quot;常见日志的命令&quot;">​</a></h4><p>一般我们会在日志配置文件中，比如 logback 配置中定义每天产生日志存放到一个文件中</p><p>在 Linux 系统中，我们查看日志文件的一些常用命令：</p><ul><li>实时监控日志的变化 <ul><li>实时监控某一个日志文件的变化：<code>tail -f xx.log</code></li><li>实时监控日志最后100行日志：<code>tail -n 100 -f xx.log</code><ul><li><ul><li><code>-n 100</code>：首先显示<code>xx.log</code>文件的最后100行内容。</li></ul></li><li><code>-f</code>：之后，随着<code>xx.log</code>文件的增长，新添加的内容会被实时显示。</li></ul></li></ul></li><li>按照行号套询 <ul><li>查询日志尾部最后100行日志：<code>tail -n 100 xx.log</code></li><li>查询日志头部开始100行日志：<code>head -n 100 xx.log</code></li><li>查询某一个日志行号区间： <ul><li>查询100行至200行的日志 <code>cat -n xx.log|tail -n +100|head -n 100</code></li></ul></li></ul></li><li>按照关键字找日志的信息 <ul><li>查询日志文件中包含debug的日志行号： <code>cat -n xx.log|grep &quot;debug&quot; </code></li></ul></li><li>按照日期查询 <ul><li><code>sed -n &#39;/2023-05-18 14:22:31.070/,/2023-05-18 14:27:14.158/p&#39; xx.log</code></li></ul></li><li>日志太多，处理方式 <ul><li>分页查询日志信息：<code>cat -n xx.log|grep &quot;debug&quot; |more</code></li><li>筛选过滤以后，输出到一个文件：<code>cat -n xx.log|grep &quot;debug&quot; &gt; debg.txt </code></li></ul></li></ul><h4 id="正常微服务接口报错写入日志是怎么操作的" tabindex="-1">正常微服务接口报错写入日志是怎么操作的 <a class="header-anchor" href="#正常微服务接口报错写入日志是怎么操作的" aria-label="Permalink to &quot;正常微服务接口报错写入日志是怎么操作的&quot;">​</a></h4><h3 id="系统设计" tabindex="-1">系统设计 <a class="header-anchor" href="#系统设计" aria-label="Permalink to &quot;系统设计&quot;">​</a></h3><h4 id="接口幂等" tabindex="-1">接口幂等 <a class="header-anchor" href="#接口幂等" aria-label="Permalink to &quot;接口幂等&quot;">​</a></h4><ul><li><a href="https://www.bilibili.com/video/BV1Hg411n779" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Hg411n779</a></li></ul><h4 id="建议不要使用分布式事务组件" tabindex="-1">建议不要使用分布式事务组件 <a class="header-anchor" href="#建议不要使用分布式事务组件" aria-label="Permalink to &quot;建议不要使用分布式事务组件&quot;">​</a></h4><p>参考： <a href="https://www.bilibili.com/video/BV1g84y1s7DH" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1g84y1s7DH</a></p><h3 id="数据库-🚩" tabindex="-1">数据库 🚩 <a class="header-anchor" href="#数据库-🚩" aria-label="Permalink to &quot;数据库  🚩&quot;">​</a></h3><h4 id="一张已经百万级别数据量的表-需要改一下字段结构或者索引-有什么合适的方式" tabindex="-1">一张已经百万级别数据量的表，需要改一下字段结构或者索引，有什么合适的方式 <a class="header-anchor" href="#一张已经百万级别数据量的表-需要改一下字段结构或者索引-有什么合适的方式" aria-label="Permalink to &quot;一张已经百万级别数据量的表，需要改一下字段结构或者索引，有什么合适的方式&quot;">​</a></h4><h4 id="分表" tabindex="-1">分表 <a class="header-anchor" href="#分表" aria-label="Permalink to &quot;分表&quot;">​</a></h4><p>参考： <a href="https://www.bilibili.com/video/BV1rg411x7zK" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1rg411x7zK</a></p><h4 id="讲一下你当时水平分表遇到的问题-以及怎么解决的" tabindex="-1">讲一下你当时水平分表遇到的问题，以及怎么解决的 <a class="header-anchor" href="#讲一下你当时水平分表遇到的问题-以及怎么解决的" aria-label="Permalink to &quot;讲一下你当时水平分表遇到的问题，以及怎么解决的&quot;">​</a></h4><h3 id="生产问题" tabindex="-1">生产问题 <a class="header-anchor" href="#生产问题" aria-label="Permalink to &quot;生产问题&quot;">​</a></h3><h4 id="生产问题怎么排查" tabindex="-1">生产问题怎么排查 <a class="header-anchor" href="#生产问题怎么排查" aria-label="Permalink to &quot;生产问题怎么排查&quot;">​</a></h4><p>已经上线的bug排查的思路：</p><ul><li>1,先分析日志，通常在业务中都会有日志的记录，或者查看系统日志，或者查看日志文件，然后定位问题</li><li>2, 远程debug(通常公司的正式环境（生产环境）是不允许远程debugl的。一般远程debug都是公司的测试环境，方便调试代码)</li></ul><p>使用 IDEA 远程 Debug 服务器的 Jar 包方法可以看一下相关教程（需要本地代码和服务器打包Jar代码保持一致）</p><p>可以大概说一下先日志排查，然后再进行测试环境远程 Debug 调试看出现的问题。</p><h4 id="怎么快速定位系统的瓶颈" tabindex="-1">怎么快速定位系统的瓶颈 <a class="header-anchor" href="#怎么快速定位系统的瓶颈" aria-label="Permalink to &quot;怎么快速定位系统的瓶颈&quot;">​</a></h4><ul><li>压测（性能测试），项目上线之前测评系统的压力 <ul><li>压测目的：给出系统当前的性能状况；定位系统性能瓶颈或潜在性能瓶颈</li><li>指标：响应时间、QPS、并发数、吞吐量、CPU利用率、内存使用率、磁盘 IO、错误率</li><li>压测工具：LoadRunner、Apache Jmeter…</li><li>后端工程师：根据压测的结果进行解决或调优（接口慢、代码报错、并发达不到要求）</li></ul></li><li>监控工具、链路追踪工具，项目上线之后监控 <ul><li>监控工具：Prometheus+Grafana</li><li>链路追踪工具：skywalking、Zipkin</li></ul></li><li>线上诊断工具Arthas (阿尔萨斯)，项目上线之后监控、排查 <ul><li>官网：<a href="https://arthas.aliyun.com/" target="_blank" rel="noreferrer">https://arthas.aliyun.com/</a></li><li>不建议说，不太了解的话。</li></ul></li></ul><p>一般还是建议从如何监控线上，排查出对应的问题，然后如何解决的去回答。</p><h4 id="cpu-飘升如何定位到代码" tabindex="-1">CPU 飘升如何定位到代码 <a class="header-anchor" href="#cpu-飘升如何定位到代码" aria-label="Permalink to &quot;CPU 飘升如何定位到代码&quot;">​</a></h4><p>参考： <a href="https://www.bilibili.com/video/BV1sP4y1F76s" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1sP4y1F76s</a></p><p>项目上线之后，CpU飙升，居高不下。触发报警。我们该如何排查问题所在？</p><p>传统的查看日志的方式</p><ul><li>1、top</li><li>2、ps -mp</li><li>3、tid转换</li><li>4、jstack打印</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240511114041.png" alt="image.png"></p><p>查看线程下进程占用 CPU 情况，TID 需要转换为 16 进制信息</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240511114130.png" alt="image.png"></p><p>根据 线程 PID 和进程 TID 查看到进程的运行状态日志</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240511114249.png" alt="image.png"></p><p>或者火焰图的方式</p><h4 id="线上服务内存溢出如何排查定位" tabindex="-1">线上服务内存溢出如何排查定位 <a class="header-anchor" href="#线上服务内存溢出如何排查定位" aria-label="Permalink to &quot;线上服务内存溢出如何排查定位&quot;">​</a></h4><ul><li>jmap (Memory Map for Java)命令用于生成堆转储快照。就是我们常说的dump文件，我们可以手动执行命令来生成dump文件。还可以使用JVM参数来配置自动生成</li><li>自动生成 <ul><li>XX:+HeapDumpOnOutofMemoryError, 可以让虚拟机在OOM异常出现之后自动生成dump文件</li><li>-XX:HeapDumpPath=path设置dump文件路径</li></ul></li><li>手动生成 <ul><li>jmap -dump:format= b.file = heap.hprof.pid</li></ul></li><li>jmap 除了生成dump也可以看到 jvm堆的数据占用情况。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240511114445.png" alt="image.png"></p><p>根据 进程 PID 生成对应的 dump 文件</p><p>生成的时候，需要将流量关掉，生成 dump 的过程中服务会停止，不会向外提供服务</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240511115142.png" alt="image.png"></p><p>通过 MAT 工具进行分析处理</p><ul><li>进入下载后的文件夹，双击 MemoryAnalyer.exe 启动，进行打开 dump 文件，选择对应 dump.dat 文件，选择第一个 Leak Suspect Reports，生成一个报告操作</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240511115454.png" alt="image.png"></p><ul><li>选择 Dominator Tree</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240511115738.png" alt="image.png"></p><ul><li><p>进入，查看占用内存情况 <img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240511115912.png" alt="image.png"></p></li><li><p>右键查看 → Java Basics → Thread Overview and Stacks 查看线程以内的情况</p></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240511120031.png" alt="image.png"></p><blockquote><p>VisualVM 工具</p></blockquote><p>生成 dump 文件：</p><ul><li>一般是设置 JVM 参数，有时候程序是直接闪退挂了，不太可能让你运行的时候使用 jmap 命令（使用 vm 参数获取 dump 文件）</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305184231.png" alt="image.png"></p><p>分析 dump 文件</p><ul><li>1、打开 VisualVM</li><li>2、选择：文件 → 装入 → （选择文件） → 打开</li><li>3、概要 → 堆转储</li><li>4、通过查看堆信息的情况，可以大概定位内存谥出是哪行代码出了问题</li></ul><h3 id="业务问题" tabindex="-1">业务问题 <a class="header-anchor" href="#业务问题" aria-label="Permalink to &quot;业务问题&quot;">​</a></h3><h4 id="库存扣减问题" tabindex="-1">库存扣减问题 <a class="header-anchor" href="#库存扣减问题" aria-label="Permalink to &quot;库存扣减问题&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240312113836.png" alt="image.png"></p><h4 id="使用-websocket-进行前后端-http-长连接操作" tabindex="-1">使用 websocket 进行前后端 http 长连接操作 <a class="header-anchor" href="#使用-websocket-进行前后端-http-长连接操作" aria-label="Permalink to &quot;使用 websocket 进行前后端 http 长连接操作&quot;">​</a></h4><h4 id="socket-监听-实时推送站点车辆信息到前端界面" tabindex="-1">socket 监听，实时推送站点车辆信息到前端界面 <a class="header-anchor" href="#socket-监听-实时推送站点车辆信息到前端界面" aria-label="Permalink to &quot;socket 监听，实时推送站点车辆信息到前端界面&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240330230550.png" alt="image.png"></p><h3 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h3><h4 id="多线程" tabindex="-1">多线程 <a class="header-anchor" href="#多线程" aria-label="Permalink to &quot;多线程&quot;">​</a></h4><p>参考看一下： <a href="https://blog.csdn.net/qq_40851232/article/details/134402593?spm=1001.2014.3001.5502" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_40851232/article/details/134402593?spm=1001.2014.3001.5502</a></p><p><a href="/java-site/面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/面试煎熬成蛋_性能优化.html">11 面试煎熬成蛋_性能优化</a></p><p>项目亮点</p>',104)])])}const b=a(o,[["render",r]]);export{d as __pageData,b as default};
